 * Component-level styling for MR SM Multi Brand Store
 */

/* ==========================================================================
   Buttons
   ========================================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-xs);
  padding: 0.75rem 1.75rem;
  font-family: var(--font-sans);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  transition: all var(--transition-base);
  text-align: center;
  white-space: nowrap;
  user-select: none;
  text-decoration: none;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  pointer-events: none;
}

/* Primary Button (Espresso with Cream text) */
.btn-primary {
  background-color: var(--color-espresso) !important;
  color: var(--color-cream) !important;
  border-color: var(--color-espresso) !important;
}

.btn-primary:hover {
  background-color: var(--color-espresso-light) !important;
  border-color: var(--color-espresso-light) !important;
  color: var(--color-white) !important;
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.btn-primary:active {
  transform: translateY(0);
}

/* Secondary Button (Mocha) */
.btn-secondary {
  background-color: var(--color-mocha) !important;
  color: var(--color-white) !important;
  border-color: var(--color-mocha) !important;
}

.btn-secondary:hover {
  background-color: var(--color-mocha-dark) !important;
  border-color: var(--color-mocha-dark) !important;
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

/* Accent Button (Caramel) */
.btn-caramel {
  background-color: var(--color-caramel) !important;
  color: var(--color-white) !important;
  border-color: var(--color-caramel) !important;
}

.btn-caramel:hover {
  background-color: var(--color-caramel-hover) !important;
  border-color: var(--color-caramel-hover) !important;
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

/* Outline Button */
.btn-outline {
  background-color: transparent !important;
  color: var(--color-espresso) !important;
  border-color: var(--color-espresso) !important;
}

.btn-outline:hover {
  background-color: var(--color-espresso) !important;
  color: var(--color-cream) !important;
  box-shadow: var(--shadow-sm);
}

.btn-outline-caramel {
  background-color: transparent !important;
  color: var(--color-caramel) !important;
  border-color: var(--color-caramel) !important;
}

.btn-outline-caramel:hover {
  background-color: var(--color-caramel) !important;
  color: var(--color-white) !important;
  box-shadow: var(--shadow-sm);
}

/* Size Modifiers */
.btn-sm {
  padding: 0.5rem 1rem;
  font-size: var(--font-size-xs);
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: var(--font-size-base);
}

.btn-full {
  width: 100%;
}

/* ==========================================================================
   Badges & Tags
   ========================================================================== */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0.25rem 0.6rem;
  font-family: var(--font-sans);
  font-size: 0.7rem;
  font-weight: var(--font-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: var(--radius-xs);
  line-height: 1;
}

.badge-caramel {
  background-color: var(--color-caramel);
  color: var(--color-white);
}

.badge-mocha {
  background-color: var(--color-mocha);
  color: var(--color-white);
}

.badge-latte {
  background-color: var(--color-latte);
  color: var(--color-espresso);
}

.badge-sale {
  background-color: #A82828;
  color: var(--color-white);
}

.badge-demo {
  background-color: var(--color-latte);
  color: var(--color-espresso);
  border: 1px dashed var(--color-mocha);
  font-size: 0.65rem;
}

/* ==========================================================================
   Product Cards
   ========================================================================== */
.product-card {
  background-color: var(--color-white);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-base), box-shadow var(--transition-base), border-color var(--transition-base);
  position: relative;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-card-hover);
  border-color: var(--color-latte-dark);
}

.product-card-image-wrap {
  position: relative;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  background-color: var(--color-latte-soft);
}

.product-card-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-smooth);
}

.product-card:hover .product-card-image {
  transform: scale(1.05);
}

.product-card-badges {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  display: flex;
  flex-direction: column;
  gap: var(--space-2xs);
  z-index: 2;
}

.product-card-body {
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.product-card-category {
  font-size: var(--font-size-xs);
  color: var(--color-caramel);
  text-transform: uppercase;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.06em;
  margin-bottom: var(--space-2xs);
}

.product-card-title {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-espresso);
  margin-bottom: var(--space-xs);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  height: 2.85em;
}

.product-card-title a:hover {
  color: var(--color-caramel);
}

.product-card-price-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-xs);
  margin-top: auto;
  padding-top: var(--space-sm);
}

.price-current {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
  color: var(--color-espresso);
}

.price-compare {
  font-size: var(--font-size-sm);
  color: var(--text-muted);
  text-decoration: line-through;
}

.price-discount {
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-bold);
  color: var(--color-caramel);
}

/* ==========================================================================
   Form Controls
   ========================================================================== */
.form-group {
  margin-bottom: var(--space-lg);
}

.form-label {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  color: var(--color-espresso);
  margin-bottom: var(--space-xs);
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: var(--font-size-base);
  color: var(--text-primary);
  background-color: var(--color-white);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--color-caramel);
  box-shadow: 0 0 0 3px var(--color-caramel-soft);
}

.form-textarea {
  resize: vertical;
  min-height: 120px;
}

.form-error {
  font-size: var(--font-size-xs);
  color: var(--status-error);
  margin-top: var(--space-2xs);
}

/* ==========================================================================
   States (Loading, Empty, Error)
   ========================================================================== */
.spinner {
  width: 36px;
  height: 36px;
  border: 3px solid var(--color-latte);
  border-top-color: var(--color-caramel);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  margin: 0 auto;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.loading-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--space-3xl) var(--space-md);
  text-align: center;
  gap: var(--space-md);
}

.empty-state {
  text-align: center;
  padding: var(--space-3xl) var(--space-lg);
  background-color: var(--color-white);
  border: 1px dashed var(--border-subtle);
  border-radius: var(--radius-md);
  max-width: 540px;
  margin: var(--space-xl) auto;
}

.empty-state-icon {
  font-size: 3rem;
  margin-bottom: var(--space-md);
  color: var(--color-caramel);
}

.empty-state h3 {
  margin-bottom: var(--space-xs);
}

.error-state {
  text-align: center;
  padding: var(--space-2xl) var(--space-lg);
  background-color: var(--status-error-bg);
  border: 1px solid #F5C6CB;
  border-radius: var(--radius-md);
  max-width: 540px;
  margin: var(--space-xl) auto;
}

.error-state h3 {
  color: var(--status-error);
  margin-bottom: var(--space-xs);
}

/* Banner / Notice */
.demo-banner {
  background-color: var(--color-latte);
  color: var(--color-espresso);
  padding: var(--space-xs) var(--space-md);
  font-size: var(--font-size-xs);
  text-align: center;
  font-weight: var(--font-weight-medium);
  border-bottom: 1px solid var(--border-subtle);
}

.demo-banner strong {
  color: var(--color-mocha);
}

/* Modal Responsive Padding */
.checkout-modal-body {
  padding: clamp(1rem, 3.5vw, 2rem);
}
