h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: var(--font-weight-semibold);
  color: var(--color-espresso);
  line-height: var(--line-height-tight);
  letter-spacing: -0.01em;
}

h1 { font-size: clamp(2rem, 4vw, var(--font-size-5xl)); }
h2 { font-size: clamp(1.75rem, 3vw, var(--font-size-3xl)); }
h3 { font-size: clamp(1.35rem, 2.5vw, var(--font-size-2xl)); }
h4 { font-size: var(--font-size-xl); }
h5 { font-size: var(--font-size-lg); }
h6 { font-size: var(--font-size-base); }

p {
  color: var(--text-secondary);
  line-height: var(--line-height-relaxed);
  margin-bottom: var(--space-md);
}

p:last-child {
  margin-bottom: 0;
}

/* Base Body & Layout Safeguards */
html, body {
  overflow-x: hidden !important;
  max-width: 100vw;
  width: 100%;
  position: relative;
  box-sizing: border-box;
}

*, *::before, *::after {
  box-sizing: border-box;
}

a {
  color: inherit;
  text-decoration: none !important;
}

a:hover {
  color: var(--color-caramel);
  text-decoration: none !important;
}

/* Layout Containers with Responsive Auto-Padding */
.container {
  width: 100%;
  max-width: var(--container-max-width) !important;
  margin-left: auto;
  margin-right: auto;
  padding-left: clamp(1rem, 4vw, var(--container-padding)) !important;
  padding-right: clamp(1rem, 4vw, var(--container-padding)) !important;
  box-sizing: border-box !important;
}

.container-narrow {
  width: 100%;
  max-width: var(--container-narrow-width) !important;
  margin-left: auto;
  margin-right: auto;
  padding-left: clamp(1rem, 4vw, var(--container-padding)) !important;
  padding-right: clamp(1rem, 4vw, var(--container-padding)) !important;
  box-sizing: border-box !important;
}

/* Responsive Button Text Safeguard for Mobile */
@media (max-width: 640px) {
  .btn-lg {
    white-space: normal !important;
    word-break: break-word !important;
    line-height: 1.35 !important;
  }
}

/* Page Section Wrappers */
.section {
  padding-top: var(--space-3xl);
  padding-bottom: var(--space-3xl);
}

.section-sm {
  padding-top: var(--space-xl);
  padding-bottom: var(--space-xl);
}

.section-latte {
  background-color: var(--color-latte-soft);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.section-espresso {
  background-color: var(--color-espresso);
  color: var(--color-cream);
}

.section-espresso h1,
.section-espresso h2,
.section-espresso h3,
.section-espresso h4 {
  color: var(--color-cream);
}

.section-espresso p {
  color: var(--color-latte);
}

/* Section Header Typography */
.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto var(--space-2xl) auto;
}

.section-eyebrow {
  display: inline-block;
  font-family: var(--font-sans);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-caramel);
  margin-bottom: var(--space-xs);
}

.section-title {
  margin-bottom: var(--space-sm);
}

.section-subtitle {
  font-size: var(--font-size-lg);
  color: var(--text-muted);
}

/* Responsive Grids */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-xl);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-xl);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-lg);
}

@media (max-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--space-md);
  }
  .grid-3 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--space-md);
  }
}

@media (max-width: 640px) {
  .grid-4, .grid-3, .grid-2 {
    grid-template-columns: repeat(1, minmax(0, 1fr)) !important;
    gap: var(--space-md) !important;
  }
  .section {
    padding-top: var(--space-xl) !important;
    padding-bottom: var(--space-xl) !important;
  }
}

/* Global 2-Column Responsive Layout for Split Pages */
.responsive-split-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2.5rem;
  align-items: start;
}

@media (max-width: 860px) {
  .responsive-split-grid {
    grid-template-columns: 1fr !important;
    gap: 1.5rem !important;
  }
}

/* Product Details Page Split Grid */
.product-details-grid {
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  gap: 3.5rem;
  margin-bottom: 4rem;
}

@media (max-width: 900px) {
  .product-details-grid {
    grid-template-columns: 1fr !important;
    gap: 2rem !important;
    margin-bottom: 2.5rem !important;
  }
}
